item.text:
{
  "packet_id": "H6-T04-2",
  "claims": [
    {
      "claim_id": "C001",
      "fields": ["state"],
      "component": {
        "component_id": "C001.main",
        "value": "The path from a new account to its first published schedule is to be treated as a history requiring traceable continuity across participants, preparation and schedule versions.",
        "scope": "Proposed framing of each new account's onboarding history.",
        "provenance": {
          "refs": [{"source_id": "P001", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the continuity framing and its dimensions."
        }
      }
    },
    {
      "claim_id": "C002",
      "fields": ["state"],
      "component": {
        "component_id": "C002.main",
        "value": "Account creation, invitations, draft saves and publication are documented event categories.",
        "scope": "The mapping's stated observation baseline; this does not assert complete capture of every instance.",
        "provenance": {
          "refs": [{"source_id": "P001", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span identifies these categories as documented."
        }
      }
    },
    {
      "claim_id": "C003",
      "fields": ["state"],
      "component": {
        "component_id": "C003.main",
        "value": "Offline preparation is unobserved in the existing event record.",
        "scope": "Initial observation coverage, before the proposed customer follow-ups.",
        "provenance": {
          "refs": [{"source_id": "P001", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span contrasts documented events with unobserved offline preparation."
        }
      }
    },
    {
      "claim_id": "C004",
      "fields": ["state"],
      "component": {
        "component_id": "C004.main",
        "value": "Whether responsibility actually transfers between people remains to be established.",
        "scope": "An unresolved feature of the onboarding process, not an asserted handoff.",
        "provenance": {
          "refs": [{"source_id": "P001", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly treats interpersonal responsibility transfer as a question."
        }
      }
    },
    {
      "claim_id": "C005",
      "fields": ["state"],
      "component": {
        "component_id": "C005.main",
        "value": "Which team information is required remains to be established.",
        "scope": "An unresolved information requirement, not an established deficiency.",
        "provenance": {
          "refs": [{"source_id": "P001", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly leaves the required team information open."
        }
      }
    },
    {
      "claim_id": "C006",
      "fields": ["state"],
      "component": {
        "component_id": "C006.main",
        "value": "The account's intended publication timing remains to be established.",
        "scope": "Account-specific intent is not supplied as a fact.",
        "provenance": {
          "refs": [{"source_id": "P001", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span identifies intended publication timing as an unresolved question."
        }
      }
    },
    {
      "claim_id": "C007",
      "fields": ["operation"],
      "component": {
        "component_id": "C007.main",
        "value": "Existing events should be linked by account and schedule identifiers, with draft-to-publication lineage checked.",
        "scope": "A bounded cohort of new accounts; the procedure proposes verification rather than assuming identifier linkage is correct.",
        "provenance": {
          "refs": [{"source_id": "P002", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the cohort bound, linkage method and lineage check."
        }
      }
    },
    {
      "claim_id": "C008",
      "fields": ["operation"],
      "component": {
        "component_id": "C008.main",
        "value": "Relevant handling or handoff events should be documented with responsibility, timing, purpose, transferred information or version, and the intended next step.",
        "scope": "Proposed documentation of relevant events; it does not establish that handoffs occur.",
        "provenance": {
          "refs": [{"source_id": "P003", "role": "SUPPORT"}, {"source_id": "P001", "role": "CONTEXT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P003 supplies the documentation proposal; P001 clarifies that actual responsibility transfers remain unresolved."
        }
      }
    },
    {
      "claim_id": "C009",
      "fields": ["operation"],
      "component": {
        "component_id": "C009.main",
        "value": "Brief customer follow-ups should document offline preparation and intended roster timing while explicitly identifying retrospective reports and unknowns.",
        "scope": "Proposed supplementary data collection; reports are not presented as direct event-log observations.",
        "provenance": {
          "refs": [{"source_id": "P004", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the collection method, subjects and epistemic labeling requirements."
        }
      }
    },
    {
      "claim_id": "C010",
      "fields": ["operation"],
      "component": {
        "component_id": "C010.main",
        "value": "History inspection should examine continuity, identity or version conflicts and unexplained transitions, with participant clarification added without replacing the original record.",
        "scope": "Proposed inspection and record-preservation procedure.",
        "provenance": {
          "refs": [{"source_id": "P005", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span describes the inspection criteria and preservation constraint."
        }
      }
    },
    {
      "claim_id": "C011",
      "fields": ["operation"],
      "component": {
        "component_id": "C011.main",
        "value": "The eight interviews may be used to generate checks to perform.",
        "scope": "An exploratory use of the interviews, without estimating prevalence.",
        "provenance": {
          "refs": [{"source_id": "P006", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span gives the interviews a check-generating role and bounds that role."
        }
      }
    },
    {
      "claim_id": "C012",
      "fields": ["operation", "limit"],
      "component": {
        "component_id": "C012.main",
        "value": "The eight interviews cannot establish how prevalent an explanation is.",
        "scope": "Prevalence claims based on this interview set.",
        "provenance": {
          "refs": [{"source_id": "P006", "role": "SUPPORT"}, {"source_id": "P023", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "Both spans state the same restriction on using the interviews to establish frequency."
        }
      }
    },
    {
      "claim_id": "C013",
      "fields": ["operation"],
      "component": {
        "component_id": "C013.main",
        "value": "The small release slot should fund one narrow product change only if corroborated histories identify a recurring, actionable handoff problem.",
        "scope": "A necessary selection condition, not a claim that such a problem has been found or that meeting the condition guarantees success.",
        "provenance": {
          "refs": [{"source_id": "P007", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the release constraint and the condition for selecting a change."
        }
      }
    },
    {
      "claim_id": "C014",
      "fields": ["operation"],
      "component": {
        "component_id": "C014.main",
        "value": "An explicit missing-information checklist is an example candidate change if the corresponding missing-information handoff problem is confirmed.",
        "scope": "An illustrative option under the corroborated, recurring and actionable problem requirement; no checklist benefit is asserted.",
        "provenance": {
          "refs": [{"source_id": "P007", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The complete span preserves both the example and its governing selection condition."
        }
      }
    },
    {
      "claim_id": "C015",
      "fields": ["operation"],
      "component": {
        "component_id": "C015.main",
        "value": "If histories remain unreliable or identify no recurring actionable problem, a presumed friction fix should not be selected.",
        "scope": "Either stated condition triggers withholding a presumed product fix.",
        "provenance": {
          "refs": [{"source_id": "P008", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly supplies the alternative conditions and the selection restriction."
        }
      }
    },
    {
      "claim_id": "C016",
      "fields": ["operation"],
      "component": {
        "component_id": "C016.main",
        "value": "If histories remain unreliable or identify no recurring actionable problem, the release slot should be used to improve the deficient recording step.",
        "scope": "Conditional resource allocation as authored. The wording presupposes an identifiable recording deficiency, but does not establish one for the branch where reliable histories reveal no recurring actionable problem.",
        "provenance": {
          "refs": [{"source_id": "P008", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The conditional proposal is directly attributable. Its unresolved presupposition is retained rather than supplied or repaired."
        }
      }
    },
    {
      "claim_id": "C017",
      "fields": ["operation"],
      "component": {
        "component_id": "C017.main",
        "value": "Before release, evaluation should specify eligible accounts, the first-publication outcome, recording checks and a common observation window covering intended roster opportunity.",
        "scope": "Prospective evaluation design; the window's duration and how it accommodates differing intended dates are unspecified.",
        "provenance": {
          "refs": [{"source_id": "P009", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the prospective design requirements without resolving their implementation."
        }
      }
    },
    {
      "claim_id": "C018",
      "fields": ["operation"],
      "component": {
        "component_id": "C018.main",
        "value": "Eligible accounts should be randomly assigned to the proposed change or the current flow if random assignment is feasible.",
        "scope": "A feasibility-conditioned design proposal, not a report of actual randomization.",
        "provenance": {
          "refs": [{"source_id": "P010", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies both the feasibility condition and the two assignment alternatives."
        }
      }
    },
    {
      "claim_id": "C019",
      "fields": ["operation"],
      "component": {
        "component_id": "C019.main",
        "value": "When random assignment is infeasible, a comparable contemporaneous cohort should be used and assignment differences documented.",
        "scope": "The fallback comparison design; comparability is a proposed requirement, not an established fact.",
        "provenance": {
          "refs": [{"source_id": "P010", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly states the fallback and its accompanying documentation requirement."
        }
      }
    },
    {
      "claim_id": "C020",
      "fields": ["operation"],
      "component": {
        "component_id": "C020.main",
        "value": "Unresolved histories should continue to be followed through the agreed observation window.",
        "scope": "Follow-up bounded by the prospectively agreed window.",
        "provenance": {
          "refs": [{"source_id": "P011", "role": "SUPPORT"}, {"source_id": "P009", "role": "CONTEXT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P011 supplies the follow-up requirement; P009 identifies the observation window."
        }
      }
    },
    {
      "claim_id": "C021",
      "fields": ["operation"],
      "component": {
        "component_id": "C021.main",
        "value": "Accounts whose publication opportunity has not yet occurred should be reported separately.",
        "scope": "Reporting treatment of accounts still awaiting their publication opportunity.",
        "provenance": {
          "refs": [{"source_id": "P011", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly specifies separate reporting for these accounts."
        }
      }
    },
    {
      "claim_id": "C022",
      "fields": ["signal"],
      "component": {
        "component_id": "C022.main",
        "value": "The proposed continuity signal is an internally consistent sequence linking account creation, responsible participants, preparation, invitations, draft versions and publication.",
        "scope": "A signal to seek, not a sequence already observed; reported offline activity must remain distinguishable from logged events.",
        "provenance": {
          "refs": [{"source_id": "P012", "role": "SUPPORT"}, {"source_id": "P016", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P012 supplies the signal and provenance distinction; P016 explicitly preserves its prospective status."
        }
      }
    },
    {
      "claim_id": "C023",
      "fields": ["operation", "signal"],
      "component": {
        "component_id": "C023.main",
        "value": "Reported offline activity should remain distinguishable from logged events.",
        "scope": "Provenance of information in reconstructed histories, including retrospectively collected reports.",
        "provenance": {
          "refs": [{"source_id": "P004", "role": "SUPPORT"}, {"source_id": "P012", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P012 states the distinction; P004 contributes the explicit labeling of retrospective reports."
        }
      }
    },
    {
      "claim_id": "C024",
      "fields": ["signal"],
      "component": {
        "component_id": "C024.main",
        "value": "Missing links are to be classified as breaks in documented continuity.",
        "scope": "A documentary classification, not a finding that a particular missing link exists or that customer behavior failed.",
        "provenance": {
          "refs": [{"source_id": "P013", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly assigns this documentary meaning to missing links."
        }
      }
    },
    {
      "claim_id": "C025",
      "fields": ["signal"],
      "component": {
        "component_id": "C025.main",
        "value": "Contradictions are to be classified as breaks in documented continuity.",
        "scope": "A documentary classification, not a finding that a particular contradiction exists.",
        "provenance": {
          "refs": [{"source_id": "P013", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly assigns this documentary meaning to contradictions."
        }
      }
    },
    {
      "claim_id": "C026",
      "fields": ["signal"],
      "component": {
        "component_id": "C026.main",
        "value": "A documented wait for a stated roster date counts as an explained interval.",
        "scope": "Conditional on documentation of the wait and a stated date; it does not guarantee later publication.",
        "provenance": {
          "refs": [{"source_id": "P014", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the documentary condition and resulting interpretation."
        }
      }
    },
    {
      "claim_id": "C027",
      "fields": ["signal"],
      "component": {
        "component_id": "C027.main",
        "value": "Silence by itself does not provide evidence of postponement.",
        "scope": "Interpretation of an unexplained absence of recorded activity.",
        "provenance": {
          "refs": [{"source_id": "P014", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly denies the inference from silence alone."
        }
      }
    },
    {
      "claim_id": "C028",
      "fields": ["signal"],
      "component": {
        "component_id": "C028.main",
        "value": "Post-release observation should assess whether documentation of the targeted handoff becomes more consistent.",
        "scope": "A proposed observation of documentary continuity, with no improvement yet reported.",
        "provenance": {
          "refs": [{"source_id": "P015", "role": "SUPPORT"}, {"source_id": "P016", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P015 specifies the observation; P016 states that it is proposed rather than completed."
        }
      }
    },
    {
      "claim_id": "C029",
      "fields": ["signal"],
      "component": {
        "component_id": "C029.main",
        "value": "Post-release observation should assess change in the proportion of accounts reaching a traceable first publication within the predefined window.",
        "scope": "A proposed, time-bounded publication measure; no direction or magnitude of change is reported.",
        "provenance": {
          "refs": [{"source_id": "P015", "role": "SUPPORT"}, {"source_id": "P016", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The bundle supplies the metric, traceability requirement, observation window and prospective status."
        }
      }
    },
    {
      "claim_id": "C030",
      "fields": ["signal"],
      "component": {
        "component_id": "C030.main",
        "value": "The signal observations are proposals rather than completed findings.",
        "scope": "The observations described in the signal field; the demonstrative may refer most immediately to the post-release observations.",
        "provenance": {
          "refs": [{"source_id": "P016", "role": "SUPPORT"}, {"source_id": "P012", "role": "CONTEXT"}, {"source_id": "P015", "role": "CONTEXT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P016 explicitly supplies prospective status. The context spans identify the observations while retaining the possible breadth of the reference."
        }
      }
    },
    {
      "claim_id": "C031",
      "fields": ["inference"],
      "component": {
        "component_id": "C031.main",
        "value": "A continuous history supports attributing the examined publication to the tracked account.",
        "scope": "A supportive identity inference, not proof that identity linkage is correct.",
        "provenance": {
          "refs": [{"source_id": "P017", "role": "SUPPORT"}, {"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P017 supplies the account attribution; P021 supplies the explicit identity-linkage limit."
        }
      }
    },
    {
      "claim_id": "C032",
      "fields": ["inference"],
      "component": {
        "component_id": "C032.main",
        "value": "A continuous history supports attributing the examined publication to the tracked schedule lineage.",
        "scope": "A supportive lineage inference, not proof of correct identity linkage.",
        "provenance": {
          "refs": [{"source_id": "P017", "role": "SUPPORT"}, {"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P017 supplies lineage attribution and P021 limits what complete histories prove about linkage."
        }
      }
    },
    {
      "claim_id": "C033",
      "fields": ["inference"],
      "component": {
        "component_id": "C033.main",
        "value": "A continuous history supports the conclusion that the publication's documented handling is accounted for.",
        "scope": "Documented handling only; completeness does not establish truthful reporting or rule out unrecorded offline work.",
        "provenance": {
          "refs": [{"source_id": "P017", "role": "SUPPORT"}, {"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The bundle supplies the documentary inference and the limits on extending it beyond the record."
        }
      }
    },
    {
      "claim_id": "C034",
      "fields": ["inference"],
      "component": {
        "component_id": "C034.main",
        "value": "Corroborated histories may identify a recurring handoff suitable for the limited release.",
        "scope": "A possible diagnostic result, not a claim that a suitable handoff has already been identified.",
        "provenance": {
          "refs": [{"source_id": "P018", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly expresses this possibility and its corroboration condition."
        }
      }
    },
    {
      "claim_id": "C035",
      "fields": ["operation", "inference"],
      "component": {
        "component_id": "C035.main",
        "value": "A gap initially calls for participant clarification or better recording.",
        "scope": "The initial response to a documentary gap; clarification must preserve the original record.",
        "provenance": {
          "refs": [{"source_id": "P005", "role": "SUPPORT"}, {"source_id": "P018", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P018 supplies the initial response rationale; P005 supplies participant clarification and the preservation constraint."
        }
      }
    },
    {
      "claim_id": "C036",
      "fields": ["inference"],
      "component": {
        "component_id": "C036.main",
        "value": "A documentary gap does not initially justify attributing a failure to the customer.",
        "scope": "Initial interpretation of a gap, without additional clarification or evidence.",
        "provenance": {
          "refs": [{"source_id": "P018", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly excludes initial customer-failure attribution."
        }
      }
    },
    {
      "claim_id": "C037",
      "fields": ["inference"],
      "component": {
        "component_id": "C037.main",
        "value": "Improved documentary continuity supports better traceability.",
        "scope": "A traceability inference, without establishing an increase in publication.",
        "provenance": {
          "refs": [{"source_id": "P019", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the inference and distinguishes it from publication improvement."
        }
      }
    },
    {
      "claim_id": "C038",
      "fields": ["signal", "inference"],
      "component": {
        "component_id": "C038.main",
        "value": "Increased first publication is an outcome distinct from improved documentary continuity or traceability.",
        "scope": "The two proposed post-release measures must not be treated as one outcome.",
        "provenance": {
          "refs": [{"source_id": "P015", "role": "SUPPORT"}, {"source_id": "P019", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P015 proposes observing both measures and P019 explicitly separates their meanings."
        }
      }
    },
    {
      "claim_id": "C039",
      "fields": ["inference"],
      "component": {
        "component_id": "C039.main",
        "value": "A publication difference can support an effect of the change when random assignment is valid, follow-up is comparable and outcome capture is reliable.",
        "scope": "Conditional causal support, not guaranteed causal certainty or a report that these conditions hold.",
        "provenance": {
          "refs": [{"source_id": "P020", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the complete conjunction of conditions and the qualified causal conclusion."
        }
      }
    },
    {
      "claim_id": "C040",
      "fields": ["inference"],
      "component": {
        "component_id": "C040.main",
        "value": "Without the stated conditions of valid random assignment, comparable follow-up and reliable outcome capture, a publication difference should be treated as an association.",
        "scope": "The fallback interpretation when the stated causal-support conditions do not hold.",
        "provenance": {
          "refs": [{"source_id": "P020", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies both the conditions referred to and the fallback interpretation."
        }
      }
    },
    {
      "claim_id": "C041",
      "fields": ["inference"],
      "component": {
        "component_id": "C041.main",
        "value": "When the stated causal-support conditions do not hold, clarified histories should guide further testing.",
        "scope": "Conditional use of histories after treating publication differences as associations.",
        "provenance": {
          "refs": [{"source_id": "P020", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly links further testing to the branch lacking those conditions."
        }
      }
    },
    {
      "claim_id": "C042",
      "fields": ["limit"],
      "component": {
        "component_id": "C042.main",
        "value": "Complete histories do not prove that reporting is truthful.",
        "scope": "An evidential limit of documentary completeness.",
        "provenance": {
          "refs": [{"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly states this limit."
        }
      }
    },
    {
      "claim_id": "C043",
      "fields": ["limit"],
      "component": {
        "component_id": "C043.main",
        "value": "Complete histories do not prove that identity linkage is correct.",
        "scope": "An evidential limit of documentary completeness.",
        "provenance": {
          "refs": [{"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly states this separate identity-linkage limit."
        }
      }
    },
    {
      "claim_id": "C044",
      "fields": ["limit"],
      "component": {
        "component_id": "C044.main",
        "value": "Complete histories do not prove the absence of unrecorded offline work.",
        "scope": "An evidential limit concerning activity outside the record.",
        "provenance": {
          "refs": [{"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly states this separate coverage limit."
        }
      }
    },
    {
      "claim_id": "C045",
      "fields": ["limit"],
      "component": {
        "component_id": "C045.main",
        "value": "Missing events do not prove abandonment.",
        "scope": "Interpretation of missing event records without additional evidence.",
        "provenance": {
          "refs": [{"source_id": "P022", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly excludes proof of abandonment from missing events."
        }
      }
    },
    {
      "claim_id": "C046",
      "fields": ["limit"],
      "component": {
        "component_id": "C046.main",
        "value": "Missing events do not prove that preparation is missing.",
        "scope": "Interpretation of missing event records without additional evidence.",
        "provenance": {
          "refs": [{"source_id": "P022", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly excludes proof of missing preparation from missing events."
        }
      }
    },
    {
      "claim_id": "C047",
      "fields": ["limit"],
